package dev.rollupbridge.core;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Loads {@code testdata/tree-vectors.json}, generated by the Solidity script {@code GenerateTreeVectors}. */
final class Vectors {
    final List<Withdrawal> withdrawals = new ArrayList<>();
    final List<Bytes32> leaves = new ArrayList<>();
    final List<Bytes32> roots = new ArrayList<>();
    final List<Bytes32> zeroHashes = new ArrayList<>();
    final List<ProofVector> proofs = new ArrayList<>();

    record ProofVector(int size, int index, List<Bytes32> proof) {}

    static Vectors load() throws IOException {
        Path dir = Path.of("").toAbsolutePath();
        while (dir != null && !Files.exists(dir.resolve("testdata/tree-vectors.json"))) {
            dir = dir.getParent();
        }
        if (dir == null) {
            throw new IOException("testdata/tree-vectors.json not found; run forge script GenerateTreeVectors");
        }
        JsonNode root = new ObjectMapper().readTree(dir.resolve("testdata/tree-vectors.json").toFile());
        Vectors v = new Vectors();
        for (JsonNode w : root.get("withdrawals")) {
            v.withdrawals.add(new Withdrawal(
                    w.get("id").asLong(),
                    w.get("sender").asText(),
                    w.get("target").asText(),
                    new BigInteger(w.get("amount").asText())));
        }
        root.get("leaves").forEach(n -> v.leaves.add(Bytes32.of(n.asText())));
        root.get("roots").forEach(n -> v.roots.add(Bytes32.of(n.asText())));
        root.get("zeroHashes").forEach(n -> v.zeroHashes.add(Bytes32.of(n.asText())));
        for (JsonNode p : root.get("proofs")) {
            List<Bytes32> proof = new ArrayList<>();
            p.get("proof").forEach(n -> proof.add(Bytes32.of(n.asText())));
            v.proofs.add(new ProofVector(p.get("size").asInt(), p.get("index").asInt(), proof));
        }
        return v;
    }
}
